'毛利': [[1300,['东波利尼西亚航海者抵达','Voyagers arrive from East Polynesia'],['火山灰层、鼠骨与树轮交叉定年,约1280—1320','Ash layers, rat bones and tree rings together give about 1280-1320']],[1450,['恐鸟灭绝','The moa are gone'],['九种恐鸟与以之为食的哈斯特鹰一同消失','All nine species, and Haast\'s eagle that hunted them']],[1769,['库克到达','Cook arrives'],['持续接触自此开始','Sustained contact begins']],[1807,['火枪战争开始','The Musket Wars begin'],['先拿到火枪的部落改写了整张部落地图','The tribes who got guns first redrew the tribal map']],[1840,['怀唐伊条约','The Treaty of Waitangi'],['英文本让出主权,毛利文本让出的是治理权','The English text cedes sovereignty; the Māori text cedes governance']],[1863,['怀卡托战争与土地没收','The Waikato war and confiscations']],[1975,['怀唐伊仲裁庭设立','The Waitangi Tribunal is created'],['专门审理历史索赔','Set up to hear historical claims']],[1987,['毛利语成为官方语言','Te reo Māori becomes official']]],
'夏威夷王国': [[1795,['卡美哈梅哈一世统一各岛','Kamehameha I unifies the islands']],[1810,['考艾岛以协议加入','Kauaʻi joins by agreement']],[1840,['第一部宪法','The first constitution']],[1843,['列强承认独立','The powers recognise independence'],['1842年美国先承认,1843年法国与英国继之;王国与二十多国有条约','The United States recognised it first in 1842, France and Britain following in 1843; it held treaties with over twenty states']],[1848,['大分地','The Māhele'],['土地变为可买卖的私产,大片流向种植园主','Land became property that could be sold, and much went to the planters']],[1887,['刺刀宪法','The Bayonet Constitution'],['武力胁迫下签署,多数原住民失去选举权','Signed under threat; most Native Hawaiians lost the vote']],[1893,['政变推翻女王','The queen is deposed'],['美舰陆战队登陆配合;克利夫兰总统事后认定不合法','US marines landed in support; President Cleveland later called it unlawful']],[1898,['美国兼并','The United States annexes Hawaii'],['1993年美国国会为1893年那次推翻正式道歉','In 1993 Congress formally apologised for the 1893 overthrow']]],
'汤加王国': [[1831,['陶法阿豪受洗,取名乔治','Tāufaʻāhau is baptised as George'],['汤加语作西奥西;他已从1820年代起逐岛统一','Siaosi in Tongan; he had been uniting the islands group by group since the 1820s']],[1845,['接过图伊卡诺库波卢头衔','He takes the Tuʻi Kanokupolu title'],['通常以这一年为现代汤加王国之始','The year usually taken as the start of the modern kingdom']],[1862,['解放法典','The emancipation code'],['平民不再无偿为酋长劳作','Commoners no longer owed unpaid labour to the chiefs']],[1875,['颁布宪法','The constitution'],['设议会,席位由世袭贵族与民选代表分担;至今仍是根本法','A parliament of hereditary nobles and elected members; still the basic law today']],[1900,['与英国签友好条约','Treaty of friendship with Britain'],['外交由英国代管,王位与内政自主;1905年起英国领事对内政的影响也加大','Britain handled foreign affairs, throne and government stayed Tongan; from 1905 the British consul gained more say at home']],[1953,['萨洛特女王雨中的敞篷马车','Queen Sālote in the rain'],['伦敦加冕典礼上她坚持不合上车篷,向人群致意','At the coronation in London she kept the carriage open and waved to the crowds']],[1970,['恢复完全独立','Full independence'],['6月4日;加入英联邦','On 4 June; within the Commonwealth']],[2010,['首次民选多数议会','First elected-majority parliament'],['国王交出大部分行政权力','The king gave up most of his executive power']],[2022,['洪阿汤加海底火山喷发','Hunga Tonga erupts'],['喷发柱五十多公里高,冲击波绕地球数圈,海底电缆断了约五个星期','A plume over fifty kilometres high, a pressure wave round the earth several times, the sea cable cut for some five weeks']]],
'欧洲殖民大洋洲': [[1788,['第一舰队抵悉尼湾','The First Fleet reaches Sydney Cove'],['十一艘船,装的主要是流放犯','Eleven ships, carrying mostly convicts']],[1840,['怀唐伊条约','The Treaty of Waitangi']],[1863,['「捉黑鸟」开始','Blackbirding begins'],['昆士兰约六万二千人,斐济另有两万七千人以上','About sixty-two thousand to Queensland, and twenty-seven thousand more to Fiji']],[1874,['斐济成为英国殖民地','Fiji becomes a British colony']],[1884,['新几内亚被英德瓜分','New Guinea is split between Britain and Germany']],[1899,['萨摩亚被德美分割','Samoa is divided between Germany and the United States']],[1942,['太平洋战争','The Pacific War'],['美日在岛屿间鏖战三年,旧秩序被打散','Three years of fighting across the islands broke the old order']],[1962,['萨摩亚独立','Samoa becomes independent'],['太平洋第一个独立国家','The first Pacific nation to go free']]],
